{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Gentle, focused guidance</title>
  <meta name="description" content="Supportive short-term packages and deeper intensives for adults seeking clearer next steps. Confidential, private sessions in {{CITY}}, {{STATE}}." />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body>
  <header class="site-header">
    <div class="pattern-wrap" aria-hidden="true">
      <svg class="pattern-svg" viewBox="0 0 600 100" preserveAspectRatio="none">
        <defs>
          <pattern id="p" width="20" height="20" patternUnits="userSpaceOnUse">
            <rect width="10" height="10" fill="#eef3f2"></rect>
            <circle cx="15" cy="5" r="2" fill="#dbeae6"></circle>
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill="url(#p)"></rect>
      </svg>
    </div>

    <nav class="nav">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <button class="nav-toggle" aria-expanded="false">☰</button>
      <ul class="nav-list">
        <li><a href="about.html">Who I Am</a></li>
        <li><a href="specialties.html">Focus Areas</a></li>
        <li><a href="approach.html">My Way</a></li>
        <li><a href="fees.html">Investment</a></li>
        <li><a href="faq.html">FAQs</a></li>
        <li><a class="primary-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></li>
      </ul>
    </nav>

    <div class="hero">
      <div class="hero-inner">
        <h1 class="hero-title">A quieter map for when decisions feel heavy</h1>
        <p class="hero-sub">Therapeutic intensives and short programs to help you notice, name, and try new moves. Private, confidential sessions in {{CITY}}, {{STATE}}.</p>
        <div class="hero-actions">
          <a id="primaryCta" class="btn btn-strong" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn btn-muted" href="about.html">Learn more about my method</a>
        </div>
      </div>
    </div>
  </header>

  <main>
    <!-- Myth vs Truth (reverse order compared to other templates) -->
    <section id="myth_vs_truth" class="section card-grid">
      <h2>Common ideas — and a different way to look at them</h2>
      <div class="grid">
        <div class="card">
          <h3>Myth: I need to fix everything before starting</h3>
          <p>Truth: Small, deliberate work can create clearer options. We begin from where you are, not from perfection.</p>
        </div>
        <div class="card">
          <h3>Myth: Therapy must be lengthy to help</h3>
          <p>Truth: Focused packages can move a specific concern forward; deeper work is available when wanted.</p>
        </div>
        <div class="card">
          <h3>Myth: I should already know the right answer</h3>
          <p>Truth: The work often surfaces new questions that gently refocus choice and action.</p>
        </div>
      </div>
    </section>

    <!-- Pillars -->
    <section id="pillars" class="section">
      <h2>How I organize the work</h2>
      <ul class="pillars-list">
        <li>
          <h4>Clarify</h4>
          <p>We map what matters now: relationships, roles, and inner experience to find leverage.</p>
        </li>
        <li>
          <h4>Try</h4>
          <p>Small experiments and specific practices you can try between sessions, adjusted to your pace.</p>
        </li>
        <li>
          <h4>Reflect</h4>
          <p>We look at what shifts, what feels different, and what comes next — without pressure to be perfect.</p>
        </li>
      </ul>
    </section>

    <!-- Pricing Comparator -->
    <section id="pricing" class="section card-grid">
      <h2>Program frames and what they typically help with</h2>
      <div class="pricing-toggle">
        <label class="switch">
          <input id="priceSwitch" type="checkbox">
          <span class="slider"></span>
        </label>
        <div class="toggle-labels">
          <span>Monthly</span>
          <span>Packages</span>
        </div>
      </div>

      <div class="pricing-grid">
        <div class="price-card">
          <h3>Guided Sprint</h3>
          <p class="price" data-month="200" data-package="540">$200</p>
          <p class="price-note">Short-focus: 4 sessions over 6 weeks.</p>
        </div>
        <div class="price-card">
          <h3>Foundational Series</h3>
          <p class="price" data-month="350" data-package="960">$350</p>
          <p class="price-note">Good for deeper shifts and skill-building.</p>
        </div>
        <div class="price-card">
          <h3>Intensive Map</h3>
          <p class="price" data-month="1200" data-package="3200">$1,200</p>
          <p class="price-note">A concentrated block for clearer direction.</p>
        </div>
      </div>
      <p class="pricing-disclaimer">Prices reflect typical frames; exact structures, billing, and insurance options are discussed in the first visit.</p>
    </section>

    <!-- Mood-to-Method selector -->
    <section id="mood" class="section split">
      <div class="mood-left">
        <h2>What feels true for you right now?</h2>
        <div class="mood-list" role="list">
          <button class="mood" data-method="steady-work" data-cta="Book a short series">Heavy, overwhelmed</button>
          <button class="mood" data-method="clarity-sprint" data-cta="Reserve a guided sprint">Uncertain, stuck</button>
          <button class="mood" data-method="transition-lab" data-cta="Plan an intensive">In transition, deciding</button>
          <button class="mood" data-method="managing-anxiety" data-cta="Start a focused package">Jumpy, anxious</button>
        </div>
      </div>
      <div class="mood-right">
        <h3 id="methodTitle">Recommended approach</h3>
        <div id="methodCard" class="method-card">
          <h4 id="methodName">Choose a state above</h4>
          <p id="methodDesc">Select one of the states to see a suggested approach and an updated next step button.</p>
          <a id="methodCta" class="btn btn-strong" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        </div>
      </div>
    </section>

    <!-- Case notes / testimonials (anonymized) -->
    <section id="case_notes" class="section">
      <h2>What people notice</h2>
      <div class="case-grid">
        <blockquote>
          <p>"Short, focused sessions gave me a few practical steps I could try immediately — the pressure eased."</p>
          <cite>— Client, 30s</cite>
        </blockquote>
        <blockquote>
          <p>"We worked on one decision at a time. It felt private and practical, not overwhelming."</p>
          <cite>— Client, 40s</cite>
        </blockquote>
      </div>
    </section>

    <!-- FAQ snippet -->
    <section id="faq" class="section">
      <h2>Quick questions</h2>
      <details>
        <summary>Do you accept insurance?</summary>
        <p>I offer receipts for out-of-network reimbursement. We can discuss billing at intake.</p>
      </details>
      <details>
        <summary>Is this online only?</summary>
        <p>I offer teletherapy and limited in-person slots depending on location and preference.</p>
      </details>
    </section>

    <!-- CTA -->
    <section id="cta" class="section cta">
      <h2>Ready to name the next step?</h2>
      <p>Book a consult to discuss what frame fits your needs — single-session options and multi-session packages are available.</p>
      <div class="cta-actions">
        <a id="finalCta" class="btn btn-strong" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <a class="btn btn-muted" href="contact.html">Contact via email</a>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="footer-inner">
      <p>Confidentiality note: Sessions are private and based on clinical confidentiality limits. Scope: therapy focuses on emotional and relational concerns — not medical emergencies.</p>
      <p>If you are in crisis or an emergency, contact local emergency services or a crisis line immediately. For non-urgent questions: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
      <p class="copyright">© <span id="year"></span> {{BUSINESS_NAME}} — Serving {{CITY}}, {{STATE}}</p>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
