{"path":"assets/css/styles.css","content":"/* Base visual system */
:root{
  --bg:#fbfdfb;
  --muted:#6b7a76;
  --accent:#2b7a74;
  --accent-2:#1f5f5a;
  --card:#ffffff;
  --radius:12px;
  --max-width:1100px;
  --gap:20px;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;
}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:#0b2b2a;line-height:1.45}
.site-header{position:relative;overflow:hidden}
.pattern-wrap{position:absolute;inset:0;opacity:.6;pointer-events:none}
nav.nav{display:flex;align-items:center;justify-content:space-between;padding:20px max(20px,calc((100% - var(--max-width))/2));gap:10px}
nav .brand{font-weight:700;color:var(--accent);text-decoration:none}
.nav-list{list-style:none;margin:0;padding:0;display:flex;gap:12px;align-items:center}
.nav-list a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:8px}
.nav-list a.primary-cta{background:var(--accent);color:#fff}
.nav-toggle{display:none}
.hero{padding:40px 20px 80px;display:flex;align-items:center}
.hero-inner{max-width:var(--max-width);margin:0 auto;text-align:left}
.hero-title{font-size:2rem;margin:0 0 10px}
.hero-sub{color:var(--muted);margin:0 0 18px}
.btn{display:inline-block;padding:10px 16px;border-radius:8px;text-decoration:none;color:inherit}
.btn-strong{background:var(--accent);color:#fff}
.btn-muted{background:transparent;border:1px solid rgba(11,43,42,.08);color:var(--muted)}
.section{max-width:var(--max-width);margin:40px auto;padding:20px;}
.card-grid .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}
.card{background:var(--card);padding:18px;border-radius:var(--radius);box-shadow:0 6px 18px rgba(11,43,42,.06)}
.pillars-list{display:flex;gap:16px;flex-wrap:wrap;list-style:none;padding:0}
.pillars-list li{flex:1 1 220px;background:var(--card);padding:16px;border-radius:12px}
.pricing-toggle{display:flex;align-items:center;gap:12px;margin-bottom:18px}
.switch{position:relative;width:56px;height:28px}
.switch input{opacity:0;width:0;height:0}
.slider{position:absolute;cursor:pointer;top:0;left:0;right:0;bottom:0;background:#dfeeea;border-radius:28px}
.slider:before{content:"";position:absolute;height:22px;width:22px;left:4px;top:3px;background:white;border-radius:50%;transition:transform .25s}
.switch input:checked + .slider{background:var(--accent)}
.switch input:checked + .slider:before{transform:translateX(28px)}
.toggle-labels{display:flex;gap:8px;color:var(--muted)}
.pricing-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}
.price-card{background:linear-gradient(180deg,#fff,#f7fbfa);padding:16px;border-radius:12px;text-align:center}
.price{font-weight:700;font-size:1.4rem;margin:8px 0}
.price-note{color:var(--muted);font-size:.95rem}
.pricing-disclaimer{font-size:.9rem;color:var(--muted);margin-top:10px}
.split{display:flex;gap:16px;flex-wrap:wrap}
.mood-left{flex:1 1 280px}
.mood-right{flex:1 1 320px}
.mood-list{display:flex;flex-direction:column;gap:10px}
.mood{padding:12px;border-radius:10px;border:1px solid rgba(11,43,42,.06);background:#fff;text-align:left}
.mood:focus{outline:2px solid var(--accent-2)}
.method-card{background:var(--card);padding:16px;border-radius:12px;box-shadow:0 10px 30px rgba(11,43,42,.05)}
.case-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
blockquote{background:var(--card);padding:14px;border-radius:10px}
.cta{text-align:center}
.cta-actions{display:flex;gap:12px;justify-content:center}
.site-footer{background:#f6faf9;padding:20px}
.footer-inner{max-width:var(--max-width);margin:0 auto;color:var(--muted);font-size:.95rem}
@media (max-width:800px){
  .nav-list{display:none}
  .nav-toggle{display:block}
  .hero-title{font-size:1.5rem}
  .split{flex-direction:column}
  .case-grid{grid-template-columns:1fr}
}
/* small interactive flourishes */
.price[data-anim="true"]{transition:all .45s cubic-bezier(.2,.9,.2,1)}
.mood .active{background:linear-gradient(90deg,#eaf6f4,#ffffff)}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Utilities
  function $(sel, ctx){ return (ctx||document).querySelector(sel) }
  function $all(sel, ctx){ return Array.from((ctx||document).querySelectorAll(sel)) }

  // Year in footer
  document.getElementById('year').textContent = new Date().getFullYear();

  // Nav toggle for mobile
  var navToggle = $('.nav-toggle');
  var navList = $('.nav-list');
  if(navToggle){
    navToggle.addEventListener('click', function(){
      var open = this.getAttribute('aria-expanded') === 'true';
      this.setAttribute('aria-expanded', !open);
      navList.style.display = open ? '' : 'flex';
    });
  }

  // Pricing comparator
  var priceSwitch = document.getElementById('priceSwitch');
  var prices = $all('.price-card .price');

  function animateNumber(el, from, to){
    var start = performance.now();
    var dur = 600;
    el.setAttribute('data-anim','true');
    function step(ts){
      var t = Math.min(1,(ts-start)/dur);
      var val = Math.round(from + (to - from) * easeOutCubic(t));
      el.textContent = formatCurrency(val);
      if(t < 1) requestAnimationFrame(step);
      else el.removeAttribute('data-anim');
    }
    requestAnimationFrame(step);
  }
  function easeOutCubic(t){ return 1 - Math.pow(1 - t, 3) }
  function formatCurrency(n){
    if(n >= 1000) return '$' + (n/1000).toFixed(n%1000===0?0:1) + 'k';
    return '$' + n;
  }

  function updatePrices(usePackage){
    prices.forEach(function(p){
      var base = usePackage ? Number(p.getAttribute('data-package')) : Number(p.getAttribute('data-month'));
      var currentText = p.textContent.replace(/[^0-9.]/g,'');
      var current = Number(currentText) || 0;
      animateNumber(p, current, base);
    });
  }

  if(priceSwitch){
    // initialize from checkbox
    updatePrices(priceSwitch.checked);
    priceSwitch.addEventListener('change', function(){
      updatePrices(this.checked);
    });
  }

  // Mood-to-Method selector
  var moodButtons = $all('.mood');
  var methodName = $('#methodName');
  var methodDesc = $('#methodDesc');
  var methodTitle = $('#methodTitle');
  var methodCta = $('#methodCta');
  var primaryCta = $('#primaryCta');
  var finalCta = $('#finalCta');

  var methods = {
    'steady-work':{
      title:'Short series for pacing',
      desc:'A regular, weekly frame to work on overwhelm, pacing, and pragmatic routines. We focus on making small adjustments and noticing what changes.',
      ctaText:'Book a short series',
      ctaUrl:'{{PRIMARY_CTA_URL}}'
    },
    'clarity-sprint':{
      title:'4-session clarity sprint',
      desc:'A tightly focused package to map a decision, test a few steps, and leave with a clear plan you can try between sessions.',
      ctaText:'Reserve a guided sprint',
      ctaUrl:'{{PRIMARY_CTA_URL}}'
    },
    'transition-lab':{
      title:'Intensive planning block',
      desc:'Concentrated sessions designed to clarify major choices and practical next steps. Useful when life is shifting quickly.',
      ctaText:'Plan an intensive',
      ctaUrl:'{{PRIMARY_CTA_URL}}'
    },
    'managing-anxiety':{
      title:'Focused package for anxious moments',
      desc:'Short-term tools and in-session skill practice to reduce reactivity and create a steadier base for decision-making.',
      ctaText:'Start a focused package',
      ctaUrl:'{{PRIMARY_CTA_URL}}'
    }
  };

  function clearActive(){
    moodButtons.forEach(function(b){ b.classList.remove('active') })
  }

  moodButtons.forEach(function(btn){
    btn.addEventListener('click', function(){
      clearActive();
      this.classList.add('active');
      var methodKey = this.getAttribute('data-method');
      var method = methods[methodKey];
      if(!method) return;
      // Morph text with subtle animation
      methodName.style.opacity = 0;
      methodDesc.style.opacity = 0;
      setTimeout(function(){
        methodName.textContent = method.title;
        methodDesc.textContent = method.desc;
        methodCta.textContent = method.ctaText;
        methodCta.href = method.ctaUrl;
        // Also update header CTA to feel contextual
        primaryCta.textContent = method.ctaText;
        primaryCta.href = method.ctaUrl;
        finalCta.textContent = method.ctaText;
        finalCta.href = method.ctaUrl;
        methodName.style.opacity = 1;
        methodDesc.style.opacity = 1;
      }, 220);
    });
  });

  // Accessibility: keyboard support for mood buttons
  moodButtons.forEach(function(b){
    b.setAttribute('tabindex', '0');
    b.addEventListener('keydown', function(e){ if(e.key === 'Enter' || e.key === ' ') { e.preventDefault(); this.click() } });
  });

})();"} 
